INSERT INTO public.categories (name) VALUES ('Hoodies'),('Jeans'),('Joggers'),('Men'),('Shirts'),('T-Shirts'),('Women') ON CONFLICT (name) DO NOTHING;
INSERT INTO public.products (sku,name,description,price,original_price,category,image_url,images,rating,reviews_count,is_new,is_trending,stock_quantity,brand,gender,sizes,colors,material,fit,care_instructions,tags) VALUES
('LKLN-HD-001','Solstice Cropped Hoodie','A cropped, boxy hoodie in brushed cotton fleece with a double-lined hood, ribbed cuffs and a hem that sits just above the waist. Soft, structured and made to layer.',2499,3299,'Hoodies','/products/women1.png',ARRAY['/products/women1.png','/products/wp3.png','/products/wp8.png']::text[],4.6,128,true,true,45,'LKLN','women',ARRAY['XS','S','M','L','XL']::text[],ARRAY['Amber','Lilac','Butter']::text[],'Heavyweight 400 GSM brushed cotton fleece','Cropped relaxed','Machine wash cold, inside out. Tumble dry low. Do not bleach.',ARRAY['hoodie','cropped','winter']::text[]),
('LKLN-SW-002','Enigma Crew Sweatshirt','An oversized crewneck sweatshirt with soft-touch embroidered lettering at the chest. Dropped shoulders and a ribbed hem give an easy luxury silhouette.',2199,2799,'Hoodies','/products/wp1.png',ARRAY['/products/wp1.png','/products/wp7.png']::text[],4.5,96,false,true,60,'LKLN','women',ARRAY['XS','S','M','L','XL']::text[],ARRAY['Black','Grey']::text[],'Organic cotton-blend French terry','Oversized','Machine wash cold. Wash dark colours separately. Iron on reverse only.',ARRAY['sweatshirt','oversized','embroidered']::text[]),
('LKLN-JK-003','Riviera Denim Jacket','A washed light-blue denim jacket with a cropped cut, brushed-metal buttons and chest flap pockets. A wardrobe staple that goes with almost everything.',4299,5499,'Women','/products/women2.png',ARRAY['/products/women2.png','/products/women2-detail.png']::text[],4.7,212,true,true,30,'LKLN','women',ARRAY['XS','S','M','L']::text[],ARRAY['Light Blue']::text[],'100% rigid cotton denim, 12 oz','Regular','Cold wash separately. Line dry. Do not tumble dry.',ARRAY['jacket','denim','layering']::text[]),
('LKLN-BL-004','Garden Floral Wrap Blouse','A pale blue floral blouse with a wrap neckline, long sleeves and a fitted waist. Lightweight viscose crepe that drapes beautifully from day to evening.',1899,2499,'Women','/products/women3.png',ARRAY['/products/women3.png','/products/wp11.png']::text[],4.4,74,true,false,38,'LKLN','women',ARRAY['XS','S','M','L']::text[],ARRAY['Blue Floral']::text[],'Viscose crepe, fully lined','Slim','Hand wash or delicate cycle. Dry flat. Steam to remove creases.',ARRAY['blouse','floral','occasion']::text[]),
('LKLN-DN-005','Indigo Stack Straight Denim','Straight-leg jeans in soft stretch denim with a mid-rise waist and a clean, tapered finish. Available in three washes that fade naturally with wear.',3499,4499,'Jeans','/products/men6.png',ARRAY['/products/men6.png','/products/men6-detail.png']::text[],4.6,187,false,true,80,'LKLN','men',ARRAY['28','30','32','34','36']::text[],ARRAY['Light Wash','Mid Indigo','Dark Indigo']::text[],'98% cotton, 2% elastane stretch denim','Straight','Wash inside out in cold water. Wash with similar colours. Line dry.',ARRAY['jeans','denim','essentials']::text[]),
('LKLN-TS-006','Everyday White Tee','A crisp white crew-neck tee in breathable combed cotton. Tailored to be neither tight nor boxy and designed to hold its shape wash after wash.',999,1299,'T-Shirts','/products/women4.png',ARRAY['/products/women4.png','/products/wp2.png']::text[],4.5,342,false,true,150,'LKLN','women',ARRAY['XS','S','M','L','XL']::text[],ARRAY['White','Black']::text[],'100% combed cotton, 180 GSM','Regular','Machine wash cold. Tumble dry low. Do not bleach.',ARRAY['tee','basic','cotton']::text[]),
('LKLN-JG-007','Noir Taped Joggers','Tapered joggers with signature LKLN logo tape down the leg, an elasticated drawcord waist and zip ankle cuffs. Made for the gym, the airport and everywhere between.',2299,2999,'Joggers','/products/men7.png',ARRAY['/products/men7.png','/products/men7-detail.png']::text[],4.6,159,true,true,70,'LKLN','men',ARRAY['S','M','L','XL','XXL']::text[],ARRAY['Black','Charcoal']::text[],'Cotton-poly interlock with logo tape','Tapered','Machine wash cold. Do not iron the printed tape. Tumble dry low.',ARRAY['joggers','athleisure','tape']::text[]),
('LKLN-TS-008','Orchid Bloom Cropped Tee','A boxy cropped tee in black cotton jersey with a hand-drawn orchid print on the chest. Soft, structured and perfect with high-rise denim.',1299,1699,'T-Shirts','/products/wp9.png',ARRAY['/products/wp9.png','/products/wp9-detail.png']::text[],4.3,58,true,false,55,'LKLN','women',ARRAY['XS','S','M','L']::text[],ARRAY['Black']::text[],'100% cotton jersey, 200 GSM','Cropped boxy','Machine wash cold, inside out. Do not tumble dry the print.',ARRAY['tee','graphic','cropped']::text[]),
('LKLN-TS-009','Statement Graphic Tee','A relaxed white tee with a bold typographic statement print. Soft ring-spun cotton and a slightly longer hem for easy everyday styling.',1199,1599,'T-Shirts','/products/wp5.png',ARRAY['/products/wp5.png','/products/wp10.png']::text[],4.2,81,false,false,90,'LKLN','women',ARRAY['XS','S','M','L','XL']::text[],ARRAY['White','Cream']::text[],'100% cotton jersey, 190 GSM','Relaxed','Machine wash cold, inside out. Do not iron on print.',ARRAY['tee','graphic','statement']::text[]),
('LKLN-JK-010','Pinstripe Bomber Jacket','A black pinstripe bomber with a zip front, ribbed collar and cuffs, and a smooth satin lining. Tailored attitude for a street-ready evening look.',4999,6499,'Women','/products/wp12.png',ARRAY['/products/wp12.png','/products/wp12-detail.png']::text[],4.8,64,true,true,25,'LKLN','women',ARRAY['XS','S','M','L']::text[],ARRAY['Black Pinstripe']::text[],'Cotton-poly twill with satin lining','Relaxed','Dry clean recommended. Do not tumble dry.',ARRAY['bomber','jacket','pinstripe']::text[]),
('LKLN-SH-011','Heritage Check Shirt','A classic buffalo-check shirt in brushed cotton flannel with a button-through front, chest pocket and curved hem. Wear it open over a white tee or buttoned up.',2599,3299,'Shirts','/products/men1.png',ARRAY['/products/men1.png','/products/men1-detail.png']::text[],4.5,143,false,true,65,'LKLN','men',ARRAY['S','M','L','XL','XXL']::text[],ARRAY['Red Check','Navy Check']::text[],'100% brushed cotton flannel','Regular','Machine wash cold. Tumble dry low. Warm iron if needed.',ARRAY['shirt','check','flannel']::text[]),
('LKLN-TS-012','Skeleton Peace Graphic Tee','An oversized black tee with a skeleton-hand peace-sign graphic on the chest. Dropped shoulders and a heavy cotton feel for a streetwear finish.',1399,1799,'T-Shirts','/products/men2.png',ARRAY['/products/men2.png','/products/men2-detail.png']::text[],4.4,102,true,true,85,'LKLN','men',ARRAY['S','M','L','XL','XXL']::text[],ARRAY['Black']::text[],'100% cotton jersey, 200 GSM','Oversized','Machine wash cold, inside out. Do not bleach.',ARRAY['tee','graphic','streetwear']::text[]),
('LKLN-TS-013','Mocha Essential Tee','An everyday crew-neck tee in soft Supima cotton and a rich mocha shade. Clean seams, a smooth hand-feel and a fit that works for any occasion.',1099,1399,'T-Shirts','/products/men3.png',ARRAY['/products/men3.png','/products/men3-detail.png']::text[],4.5,176,false,false,120,'LKLN','men',ARRAY['S','M','L','XL','XXL']::text[],ARRAY['Mocha','Olive','Sand']::text[],'Supima cotton jersey, 190 GSM','Regular','Machine wash cold. Tumble dry low. Do not bleach.',ARRAY['tee','basic','supima']::text[]),
('LKLN-PL-014','Sage Pique Polo','A relaxed pique polo in a soft sage tone with a ribbed collar and two-button placket. Smart enough for the office, easy enough for the weekend.',1799,2299,'Shirts','/products/men4.png',ARRAY['/products/men4.png','/products/men4-detail.png']::text[],4.3,69,false,false,75,'LKLN','men',ARRAY['S','M','L','XL','XXL']::text[],ARRAY['Sage','Navy','White']::text[],'100% cotton pique, 220 GSM','Regular','Machine wash cold. Do not bleach. Iron on low heat.',ARRAY['polo','pique','smart-casual']::text[]),
('LKLN-HD-015','Forest Pullover Hoodie','A heavyweight pullover hoodie in deep forest green with a kangaroo pocket, double-lined hood and ribbed trims. A warm, premium layer for cooler days.',2799,3499,'Hoodies','/products/men5.png',ARRAY['/products/men5.png','/products/men5-detail.png']::text[],4.7,201,true,true,50,'LKLN','men',ARRAY['S','M','L','XL','XXL']::text[],ARRAY['Forest Green','Black','Grey Melange']::text[],'Heavyweight 420 GSM brushed fleece','Relaxed','Machine wash cold, inside out. Tumble dry low.',ARRAY['hoodie','pullover','winter']::text[])
